package com.marketplace;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import org.testcontainers.containers.PostgreSQLContainer;import org.testcontainers.junit.jupiter.*;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.*;import org.springframework.beans.factory.annotation.Autowired;import java.util.*;import java.util.concurrent.*;import java.math.*;
/** Requires Docker. Uses real PostgreSQL, never H2 or a mocked inventory repository. */
@Testcontainers(disabledWithoutDocker=true) @SpringBootTest class PostgresIntegrationTest {
 @Container static PostgreSQLContainer<?> pg=new PostgreSQLContainer<>("postgres:16.6-alpine");
 @DynamicPropertySource static void db(DynamicPropertyRegistry r){r.add("spring.datasource.url",pg::getJdbcUrl);r.add("spring.datasource.username",pg::getUsername);r.add("spring.datasource.password",pg::getPassword);r.add("management.health.redis.enabled",()->false);}
 @Autowired Db d;@Autowired Commerce c;@Autowired Orders orders;
 long uid,addr,vid;
 @BeforeEach void prepare(){uid=d.id("insert into users(email,password,name,role) values(?, 'unused','Test Customer','CUSTOMER') returning id",UUID.randomUUID()+"@test.local");addr=d.id("insert into addresses(user_id,name,line1,city,state,zip) values(?,'Test','1 Test St','Lowell','MA','01854') returning id",uid);vid=d.id("insert into variants(product_id,sku,color,price,original_price,stock) values(1,?,'Test',10,15,1) returning id",UUID.randomUUID().toString());cart(uid,vid);}
 void cart(long u,long v){d.exec("insert into cart_items values(?,?,1) on conflict(user_id,variant_id) do update set quantity=1",u,v);}
 Commerce.Checkout body(String mode){return new Commerce.Checkout(addr,"STANDARD","",mode);}
 @Test void concurrentLastUnitHasExactlyOneWinner()throws Exception {long second=d.id("insert into users(email,password,name,role) values(?,'unused','Second','CUSTOMER') returning id",UUID.randomUUID()+"@test.local");long ad=d.id("insert into addresses(user_id,name,line1,city,state,zip) values(?,'Second','2 Test','Lowell','MA','01854') returning id",second);cart(second,vid);var latch=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{Callable<Boolean> first=()->{latch.await();try{c.checkout(uid,UUID.randomUUID().toString(),body("success"));return true;}catch(Failure f){assertEquals("OUT_OF_STOCK",f.code);return false;}};Callable<Boolean> next=()->{latch.await();try{c.checkout(second,UUID.randomUUID().toString(),new Commerce.Checkout(ad,"STANDARD","","success"));return true;}catch(Failure f){assertEquals("OUT_OF_STOCK",f.code);return false;}};var x=pool.submit(first);var y=pool.submit(next);latch.countDown();assertNotEquals(x.get(20,TimeUnit.SECONDS),y.get(20,TimeUnit.SECONDS));assertEquals(0,d.id("select stock from variants where id=?",vid));assertEquals(1,d.id("select count(*) from inventory_ledger where variant_id=? and reason='SOLD'",vid));}finally{pool.shutdownNow();}}
 @Test void duplicateCheckoutAndCallbacksDoNotDuplicateStockDeduction(){String key=UUID.randomUUID().toString();var o=c.checkout(uid,key,body("success"));assertEquals(o.get("id"),c.checkout(uid,key,body("success")).get("id"));c.settle(Db.n(o,"id"),"callback-"+key,"success");c.settle(Db.n(o,"id"),"callback-"+key,"success");assertEquals(0,d.id("select stock from variants where id=?",vid));assertEquals(1,d.id("select count(*) from orders where user_id=?",uid));}
 @Test void failedPaymentReleasesStock(){var o=c.checkout(uid,UUID.randomUUID().toString(),body("decline"));assertEquals("FAILED",o.get("payment_state"));assertEquals(1,d.id("select stock from variants where id=?",vid));assertEquals(0,d.id("select reserved from variants where id=?",vid));}
 @Test void expiredReservationAndLatePaymentRequiresRefund(){var o=c.checkout(uid,UUID.randomUUID().toString(),body("timeout"));long id=Db.n(o,"id");d.exec("update orders set expires_at=now()-interval '1 second' where id=?",id);c.expire();assertEquals(0,d.id("select reserved from variants where id=?",vid));assertEquals("REFUND_REQUIRED",c.settle(id,"late-"+id,"success").get("payment_state"));assertEquals(1,d.id("select stock from variants where id=?",vid));}
 @Test void cancellationRefundIsIdempotent(){var o=c.checkout(uid,UUID.randomUUID().toString(),body("success"));long id=Db.n(o,"id");c.cancel(uid,id);c.cancel(uid,id);assertEquals(1,d.id("select stock from variants where id=?",vid));assertEquals(1,d.id("select count(*) from refunds where order_id=?",id));}
 @Test void wrongOrderOwnerCannotCancel(){var o=c.checkout(uid,UUID.randomUUID().toString(),body("success"));assertThrows(Failure.class,()->c.cancel(999999,Db.n(o,"id")));}
 @Test void checkoutNeverTrustsClientPrices(){var t=c.quote(uid,body("success"));assertEquals(new BigDecimal("10.00"),t.subtotal());assertEquals(new BigDecimal("0.63"),t.tax());}
 @Test void expiredCouponRejected(){String code="QA"+uid;d.exec("insert into promotions(code,kind,amount,minimum,max_discount,starts,ends) values(?,'PERCENT',10,0,50,now()-interval '2 days',now()-interval '1 day')",code);assertThrows(Failure.class,()->c.quote(uid,new Commerce.Checkout(addr,"STANDARD",code,"success")));}
 @Test void jdbcJsonbOrderAddressIsPlainJsonAndCancellationReflectsFulfillment(){var o=c.checkout(uid,UUID.randomUUID().toString(),body("success"));long id=Db.n(o,"id");var detail=orders.detail(id);assertEquals(Map.of("name","Test","line1","1 Test St","city","Lowell","state","MA","zip","01854"),detail.get("address"));assertEquals(true,detail.get("can_cancel"));d.exec("update seller_orders set fulfillment='SHIPPED' where order_id=?",id);assertEquals(false,orders.detail(id).get("can_cancel"));assertThrows(Failure.class,()->c.cancel(uid,id));}
}
